INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Gehört die IP-Adresse 10.0.0.1 zur Klasse A?', 2, '[{"text": "Ja", "correct": true, "because": "Klasse A umfasst 0.0.0.0 bis 127.255.255.255"}, {"text": "Nein", "correct": false, "because": "10.0.0.1 liegt im Bereich von Klasse A"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Adresse 192.168.1.1 Teil der Klasse D?', 2, '[{"text": "Nein", "correct": true, "because": "192.168.1.1 gehört zu Klasse C (192.0.0.0 - 223.255.255.255)"}, {"text": "Ja", "correct": false, "because": "Klasse D beginnt bei 224.0.0.0"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Klasse-B-Adresse für Multicast verwendet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Multicast ist Klasse D (224.0.0.0 - 239.255.255.255)"}, {"text": "Ja", "correct": false, "because": "Klasse B ist für Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Beginnt eine Klasse-C-Adresse immer mit einer Zahl zwischen 192 und 223?', 2, '[{"text": "Ja", "correct": true, "because": "Klasse C reicht von 192.0.0.0 bis 223.255.255.255"}, {"text": "Nein", "correct": false, "because": "Das ist die Definition von Klasse C"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Adressen der Klasse E für normale Netzwerke nutzbar?', 2, '[{"text": "Nein", "correct": true, "because": "Klasse E (240.0.0.0 - 255.255.255.255) ist für experimentelle Zwecke reserviert"}, {"text": "Ja", "correct": false, "because": "Sie sind nicht für den regulären Einsatz"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Klasse umfasst den Bereich 128.0.0.0 bis 191.255.255.255?', 2, '[{"text": "Klasse B", "correct": true, "because": "Das ist der Bereich von Klasse B"}, {"text": "Klasse A", "correct": false, "because": "A endet bei 127.255.255.255"}, {"text": "Klasse C", "correct": false, "because": "C beginnt bei 192.0.0.0"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche IP-Adresse gehört zur Klasse C?', 3, '[{"text": "192.168.10.1", "correct": true, "because": "Sie liegt im Bereich 192.0.0.0 - 223.255.255.255"}, {"text": "172.16.1.1", "correct": false, "because": "Das ist Klasse B"}, {"text": "10.10.10.10", "correct": false, "because": "Das ist Klasse A"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klasse wird für Multicast-Adressen verwendet?', 2, '[{"text": "Klasse D", "correct": true, "because": "224.0.0.0 - 239.255.255.255 ist für Multicast reserviert"}, {"text": "Klasse B", "correct": false, "because": "B ist für Unicast"}, {"text": "Klasse E", "correct": false, "because": "E ist experimentell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klasse hat die meisten verfügbaren Netzwerke?', 2, '[{"text": "Klasse C", "correct": true, "because": "C hat die meisten Netzwerke, aber wenige Hosts pro Netz"}, {"text": "Klasse A", "correct": false, "because": "A hat wenige Netzwerke, viele Hosts"}, {"text": "Klasse B", "correct": false, "because": "B liegt dazwischen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Adressbereich gehört zur Klasse E?', 2, '[{"text": "240.0.0.0 - 255.255.255.255", "correct": true, "because": "Das ist der Bereich von Klasse E"}, {"text": "224.0.0.0 - 239.255.255.255", "correct": false, "because": "Das ist Klasse D"}, {"text": "192.0.0.0 - 223.255.255.255", "correct": false, "because": "Das ist Klasse C"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Adressen gehören zur Klasse A?', 4, '[{"text": "10.0.0.1", "correct": true, "because": "Liegt im Bereich 0.0.0.0 - 127.255.255.255"}, {"text": "172.16.0.1", "correct": false, "because": "Das ist Klasse B"}, {"text": "127.0.0.1", "correct": true, "because": "Liegt in Klasse A"}, {"text": "192.168.1.1", "correct": false, "because": "Das ist Klasse C"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klassen sind für normale Unicast-Netzwerke gedacht?', 3, '[{"text": "Klasse A", "correct": true, "because": "Für große Netzwerke"}, {"text": "Klasse B", "correct": true, "because": "Für mittlere Netzwerke"}, {"text": "Klasse C", "correct": true, "because": "Für kleine Netzwerke"}, {"text": "Klasse D", "correct": false, "because": "Das ist Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen über Klasse B sind korrekt?', 4, '[{"text": "Bereich: 128.0.0.0 - 191.255.255.255", "correct": true, "because": "Das ist der Bereich von Klasse B"}, {"text": "Geeignet für mittelgroße Netzwerke", "correct": true, "because": "B bietet eine gute Balance"}, {"text": "Verwendet für Multicast", "correct": false, "because": "Multicast ist Klasse D"}, {"text": "Beispiel: 172.16.0.1", "correct": true, "because": "Liegt in Klasse B"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klassen haben spezielle Zwecke?', 3, '[{"text": "Klasse A", "correct": false, "because": "A ist für Unicast"}, {"text": "Klasse D", "correct": true, "because": "Multicast (224.0.0.0 - 239.255.255.255)"}, {"text": "Klasse E", "correct": true, "because": "Experimentell (240.0.0.0 - 255.255.255.255)"}, {"text": "Klasse C", "correct": false, "because": "C ist für Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adressen sind keine Klasse-C-Adressen?', 3, '[{"text": "192.168.0.1", "correct": false, "because": "Liegt in Klasse C"}, {"text": "10.10.10.10", "correct": true, "because": "Liegt in Klasse A"}, {"text": "224.1.2.3", "correct": true, "because": "Liegt in Klasse D"}, {"text": "223.255.255.254", "correct": false, "because": "Liegt in Klasse C"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Klasse A reicht bis 127.255.255.255. b) Klasse C ist für Multicast gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "A ist korrekt, C ist Unicast"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klasse D beginnt bei 224.0.0.0. b) Klasse B hat mehr Netzwerke als Klasse C.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "D ist korrekt, B hat weniger Netzwerke als C"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Klasse E ist experimentell. b) Klasse A hat wenige Hosts pro Netzwerk.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "E ist experimentell, A hat viele Hosts"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) 172.16.0.1 ist Klasse B. b) 192.168.1.1 ist Klasse D.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "172.16.0.1 ist B, 192.168.1.1 ist C"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Klasse C hat viele Netzwerke und wenige Hosts. b) Klasse E ist für normale Nutzung geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "C ist korrekt, E ist experimentell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

